func (ar *AssetRegistryContract) TransferAssetsByOwner(ctx contractapi.TransactionContextInterface, fromOwner string, toOwner string) error {
    // Verify caller is the current owner or admin
    clientID, err := ctx.GetClientIdentity().GetID()
    if err != nil {
        return fmt.Errorf("failed to get client identity: %v", err)
    }

    // Check if caller is authorized to transfer
    if clientID != fromOwner {
        mspID, _ := ctx.GetClientIdentity().GetMSPID()
        if mspID != "AdminMSP" {
            return fmt.Errorf("caller not authorized to transfer assets from %s", fromOwner)
        }
    }
    // ... rest of function
}
```

